from pathlib import Path
import base64, gzip

FILES = {
    'HuymaierConsole.ps1': '',
    'HuymaierEmulatorPlatforms.ps1': '',
    'HuymaierEmulatorInstaller.ps1': '',
    'HuymaierSteamWorker.ps1': '',
    'HuymaierSteamOwnership.ps1': '',
    'Native/HuymaierConsole.ConsolePlatforms.cs': '',
    'Native/HuymaierConsole.NativeApp.cs': '',
    'Native/HuymaierConsole.Ps1.cs': '',
    'manifest.json': '',
    'RELEASE_NOTES.txt': '',
}
CHECKS = {
    'HuymaierConsole.ps1': "$script:AppVersion = '0.26.3'",
    'HuymaierEmulatorPlatforms.ps1': 'function Start-HcEmulatorPlatform',
    'HuymaierSteamWorker.ps1': 'function Refresh-SteamCatalog',
    'HuymaierSteamOwnership.ps1': 'function Merge-HcSteamOwnedLibrary',
    'Native/HuymaierConsole.ConsolePlatforms.cs': 'public sealed class ConsolePlatformWindow',
    'Native/HuymaierConsole.NativeApp.cs': 'public sealed class NativeBridge',
    'Native/HuymaierConsole.Ps1.cs': 'public sealed class Ps1ClassicWindow',
    'manifest.json': '"version": "0.26.3"',
    'RELEASE_NOTES.txt': 'Huymaier Console',
}
for path, marker in CHECKS.items():
    p=Path(path)
    if not p.exists(): raise SystemExit(f'Expected baseline file is missing: {path}')
    text=p.read_text(encoding='utf-8-sig', errors='strict')
    if marker not in text: raise SystemExit(f'Baseline guard failed for {path}: {marker}')

for path, payload in FILES.items():
    p=Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(gzip.decompress(base64.b64decode(payload)))
print('Applied authentic console/emulator integration production batch to', len(FILES), 'files')
